[[ ## document ## ]]
{
  "title": "FY2026 Audit Calendar — Harbor Light",
  "path": "engagements/harbor-light/planning/fy2026-audit-calendar.docx",
  "document": {
    "blocks": [
      {
        "kind": "heading",
        "level": 1,
        "text": "FY2026 Audit Calendar — Harbor Light"
      },
      {
        "kind": "paragraph",
        "text": "Prepared by: Imogen Carraway, Audit Manager (senior). This calendar integrates Harbor Light's FY2026 fieldwork, interim procedures, and reporting deadlines with the firm's engagement-letter, PBC, time-and-billing, tax, and rate-sheet policies. The client's fiscal year ends December 31, 2026."
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "1. Planning Phase (May – July 2026)"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "May 15: Issue engagement letter (per Engagement Letter Policy v3.2) — signed copy due back by June 1.",
          "June 5: Finalize risk assessment and materiality; document in planning memo.",
          "June 12: Issue preliminary PBC request list (per PBC Policy v2.1) to Harbor Light's controller.",
          "July 1: Hold planning meeting with client; confirm key dates and contacts.",
          "July 15: Deadline for client to return signed engagement letter; if not received, escalate to partner per policy."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "2. Interim Procedures (August – October 2026)"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "August 3–14: Interim fieldwork — walkthroughs, controls testing, and substantive procedures on cash, payroll, and revenue recognition.",
          "September 1: Update time & billing entries for all interim work (per Time & Billing Policy v4.0) — entries must be posted by September 15 to meet monthly billing cycle.",
          "September 30: Complete and review interim testing; clear all open review notes.",
          "October 15: Issue interim management letter to client (draft for partner approval by October 5)."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "3. Year-End Fieldwork (January – February 2027)"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "January 4: Kickoff meeting with client; confirm PBC status and completeness.",
          "January 5–30: Fieldwork — inventory observation (January 5–9), confirmations (bank, A/R, A/P), journal entry testing, and substantive procedures on all significant accounts.",
          "February 10: Final PBC deadline — all outstanding items must be received; otherwise document per PBC Policy escalation.",
          "February 15: Complete fieldwork; exit meeting with client."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "4. Tax Workflow (February – March 2027)"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "February 16–28: Provide audit package to tax team (per Tax Workflow Policy v1.8) — including final trial balance, tax basis adjustments, and related-party schedules.",
          "March 10: Tax team returns completed tax returns and provisions for audit review.",
          "March 15: Audit manager and partner review tax workpapers; resolve open items.",
          "March 20: Deliver final tax returns to client for signature."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "5. Reporting & Billing (March – April 2027)"
      },
      {
        "kind": "list",
        "ordered": false,
        "items": [
          "March 25: Draft audit report and financial statements; partner review.",
          "April 1: Issue signed audit report (PDF, per Issued Documents Policy) — this is the issued version, no further edits.",
          "April 5: Finalize management letter and deliver to client.",
          "April 10: Close out time & billing — all hours and expenses must be posted by April 12 to generate final invoice.",
          "April 15: Generate and send final invoice using current rate sheet (per Rate Sheet Policy v5.1, effective January 2027)."
        ]
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "6. Key Policy References"
      },
      {
        "kind": "table",
        "columns": ["Policy", "Version", "Applicable Date", "Responsible Party"],
        "rows": [
          ["Engagement Letter Policy", "v3.2", "May 2026", "Manager / Partner"],
          ["PBC Policy", "v2.1", "June 2026 – Feb 2027", "Manager / Client"],
          ["Time & Billing Policy", "v4.0", "Throughout", "All staff"],
          ["Tax Workflow Policy", "v1.8", "Feb – Mar 2027", "Tax team / Audit"],
          ["Rate Sheet Policy", "v5.1", "Jan 2027", "Billing / Manager"]
        ]
      },
      {
        "kind": "paragraph",
        "text": "Any changes to these dates must be approved by the engagement partner and communicated to the client in writing at least two weeks in advance. Questions: contact Imogen Carraway, ext. 241."
      }
    ]
  }
}
